import{_ as o,o as t,c as i,a2 as n}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"Epic: Shell","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-mobile/blob/main/docs/epics/shell.md"},"headers":[],"relativePath":"apps/mobile/epics/shell.md","filePath":"apps/mobile/epics/shell.md"}'),a={name:"apps/mobile/epics/shell.md"};function s(d,e,r,c,l,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="epic-shell" tabindex="-1">Epic: Shell <a class="header-anchor" href="#epic-shell" aria-label="Permalink to &quot;Epic: Shell&quot;">​</a></h1><blockquote><p>The Capacitor scaffold itself — onboarding, instance persistence, WebView loading, navigation policy. This is the reason this repository exists, and the direct functional port of the shipped <code>sovereign-desktop</code> shell.</p></blockquote><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>⏳ In Progress — task 20.1 scaffold implemented and verified on iOS Simulator, Android Emulator, and a real physical iPhone, including a real Android-specific back-navigation bug found and fixed (see task detail below); not yet ✅ pending physical-device sign-off on Android.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Everything in this epic is native-shell-only concerns, per <a href="./../../CONCEPT.html">CONCEPT.md</a> and <a href="./../adrs/0002-universal-one-binary-distribution.html">ADR 0002</a>: first-launch instance URL onboarding, persistent ordered instance storage, WebView boot flow, and multi-instance switching. No auth, role, or plugin-permission logic is duplicated in native code anywhere in this epic.</p><p>Largely a <strong>port</strong> of the already-shipped <code>sovereign-desktop</code> (Tauri) shell — see the mapping table in sovereign workstream 0002&#39;s leg 4 detail:</p><table tabindex="0"><thead><tr><th><code>sovereign-desktop</code> (shipped)</th><th><code>sovereign-mobile</code> equivalent</th></tr></thead><tbody><tr><td><code>src/onboarding.ts</code></td><td>Same flow, Capacitor</td></tr><tr><td><code>src/store.ts</code> (<code>plugin-store</code>)</td><td><code>@capacitor/preferences</code></td></tr><tr><td><code>src/main.ts</code> boot flow</td><td>Identical logic</td></tr><tr><td><code>index.html</code> onboarding UI</td><td>Reusable with minimal change</td></tr><tr><td><code>.github/workflows/release.yml</code></td><td>Same shape, iOS/Android artifacts</td></tr></tbody></table><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><h4 id="⏳-20-1-—-capacitor-shell-scaffold" tabindex="-1">⏳ 20.1 — Capacitor shell scaffold <a class="header-anchor" href="#⏳-20-1-—-capacitor-shell-scaffold" aria-label="Permalink to &quot;⏳ 20.1 — Capacitor shell scaffold&quot;">​</a></h4><p><strong>Goal:</strong> Bootstrap this repo with a working Capacitor shell for iOS and Android: first-launch instance URL onboarding, persistent instance storage, WebView loading, navigation policy, and multiple-instance switching.</p><p><strong>Deliverables:</strong></p><ul><li>Capacitor app scaffold with committed iOS and Android project files.</li><li>First-launch instance URL onboarding UI.</li><li>Persistent ordered instance list storage (<code>@capacitor/preferences</code>).</li><li>WebView boot flow: stored instance → load; no stored instance → onboarding.</li><li>Multiple-instance add, remove, and switch flows.</li><li>Primary WebView navigation policy that keeps configured Sovereign instances in-app and opens external links outside the shell.</li><li>Local development instructions for iOS Simulator and Android Emulator.</li><li>Document required local tooling: Node, pnpm, Xcode, Android Studio, CocoaPods, Capacitor CLI (see <a href="./../../CONTRIBUTING.html">CONTRIBUTING.md</a>).</li></ul><p><strong>Dependencies:</strong> Sovereign RFC 0058. Validated against <code>/api/health</code> until sovereign epic task 20.2 (instance validation endpoint, a <code>sovereign</code> monorepo task) shipped; now validates against the richer <code>/api/instance</code> endpoint it added — see <a href="./../adrs/0002-universal-one-binary-distribution.html">ADR 0002</a>.</p><p><strong>Technical notes:</strong></p><ul><li><code>server.url</code> → the remote instance over <code>https</code>. Never bundle assets behind <code>capacitor://</code> — see <a href="./../adrs/0005-server-url-not-bundled-assets.html">ADR 0005</a>.</li><li>Navigation policy: keep configured instances in the primary WebView; open external links in the system browser. Sovereign RFC 0058 requires this explicitly.</li><li><strong>Verify what the shipped desktop shell actually validates against before copying it.</strong> Sovereign epic task 17.1&#39;s text says <code>/api/admin/health</code> (admin-key-gated, would 403); sovereign RFC 0038&#39;s changelog says it was corrected to <code>/api/health</code>. Confirm which is current in the shipped <code>sovereign-desktop</code> code before porting, and note the finding here.</li><li>Offline scope comes from <a href="./../research/0003-webview-offline-behavior.html">research 0003</a>&#39;s finding, not from optimism.</li></ul><p><strong>Review checklist — status as of 2026-08-02, tested against a real instance (<code>sovereign.openfs.io</code>) on both iOS Simulator and Android Emulator:</strong></p><ul><li>✅ App opens in iOS Simulator — built with <code>xcodebuild</code> against the real Capacitor 8.4.2 SPM package, installed and launched via <code>xcrun simctl</code> on two separate simulator instances (iPhone 17, iPhone 17 Pro).</li><li>✅ App opens in Android Emulator — this environment had no JDK 21 or Android SDK at all; both were installed directly into this repo&#39;s gitignored <code>.toolchain/</code> (not via Homebrew — this machine&#39;s Homebrew Cellar has broken directory ownership requiring a <code>sudo chown</code> only the machine owner can run, so JDK 21 and the SDK cmdline-tools were downloaded and extracted directly instead). <code>./gradlew assembleDebug</code><strong>succeeded</strong> against the real Capacitor Android 8.4.2 API. Built, installed, and launched on a freshly created arm64-v8a API 34 AVD via <code>adb</code>.</li><li>✅ First launch shows instance URL onboarding — confirmed by screenshot on both platforms, and by successfully connecting to a real instance on both.</li><li>✅ A valid saved instance loads in the WebView on restart — verified on both platforms: force-stopped and relaunched the app after connecting; it loaded <code>sovereign.openfs.io</code>&#39;s real sign-in page directly, no onboarding shown.</li><li>✅ Users can add, remove, and switch between at least two instances — verified on both platforms. iOS confirmed 2026-08-02. Android confirmed 2026-08-06: added <code>sovereign.openfs.io</code> and a local <code>sovereign</code> dev server (<code>http://10.0.2.2:3000</code>, the emulator&#39;s address for the host&#39;s <code>localhost:3000</code>) as two real instances side by side on a fresh <code>sovereign_mobile_test</code> AVD; both listed correctly; switched into the first (openfs.io, confirmed by no new request landing on the local dev server&#39;s logs) and then the second (confirmed by fresh <code>GET /</code> and <code>GET /api/verify</code> requests appearing in the local dev server&#39;s own log at the moment of the tap); removed a stored instance cleanly, returning to onboarding. iOS verification: added <code>sovereign.openfs.io</code> and a local <code>sovereign</code> dev server (<code>http://localhost:3000</code>) as two real instances side by side, confirmed both listed with their real names (<code>sovereign.openfs.io</code>, <code>Sovereign</code>) via <code>/api/instance</code>, and removed the second cleanly.</li><li>✅ External links do not silently navigate the primary WebView away from the configured instance — <strong>found and fixed a real bug in the process, confirmed on both platforms</strong>: see <a href="./../adrs/0007-navigation-policy-enforcement.html">ADR 0007</a>&#39;s Verified section. The same-origin case was being forwarded to Capacitor&#39;s own default handler on both iOS and Android, which redirected it externally — the exact opposite of what RFC 0058 requires. Fixed and re-verified on both: connect, restart, and (on iOS) remove/re-add/switch all correctly stay in-app; on Android, <code>dumpsys activity activities</code> confirmed <code>fs.sovereign.mobile/.MainActivity</code> stayed the foreground activity through the same flow. The cross-origin (cancel + open externally) branch itself is still not click-tested against a real external link on either platform.</li><li>✅ The history-based back-navigation instance-switch affordance (<a href="./../adrs/0006-history-based-instance-switch-affordance.html">ADR 0006</a>) — <strong>confirmed working on both platforms, including the cold-relaunch case, as of 2026-08-06.</strong> This entry went through three revisions in one session — recorded here in full because the middle revisions are a useful record of what <em>didn&#39;t</em> work and why, not just noise: <ol><li>First revision (based on user-initiated-navigation testing only) declared this fully resolved on Android. <strong>Wrong</strong> — it never tested the cold-relaunch path.</li><li>Second revision, after specifically testing cold-relaunch (force-stop the app, or let Android kill it in the background, then reopen it — <code>boot()</code>&#39;s automatic <code>location.assign()</code> on launch): found it reliably <strong>broken</strong>, 8/8 consecutive back-presses failing to reach the instance manager on two independent clean installs. Hypothesized a lingering IME input connection (<code>adb shell dumpsys input_method</code> showed the WebView registered as the served view immediately after the redirect, before any tap).</li><li><strong>This revision, after actually fixing it</strong>: the IME theory turned out to be a correlation, not the cause — clearing WebView focus (including with delayed retries, to rule out a hydration-timing race) did not fix it. Instrumenting <code>Activity.dispatchKeyEvent</code> directly revealed the real bug: the WebView&#39;s own <code>canGoBack()</code> reports <code>false</code> and <code>goBack()</code> silently no-ops in this state, even though <code>copyBackForwardList()</code> correctly shows two history entries with the current index past the first — a genuine WebView/Chromium internal-state bug tied to this shell&#39;s early, JS-triggered, cross-origin redirect on cold launch, not an app logic error. <strong>Fixed</strong> by bypassing the broken mechanism entirely: <code>MainActivity.java</code>&#39;s <code>dispatchKeyEvent</code> now checks the WebView&#39;s current URL directly and, on back-press from a loaded remote instance, explicitly <code>loadUrl()</code>s the known local manage URL instead of trusting <code>goBack()</code>. Verified against the exact prior repro — clean install, connect, force-stop, relaunch, back-press — across three independent clean installs, all succeeding on the first press, with no regression to the already-working switch-via-row-tap and back-from-that-state paths. See <a href="./../adrs/0006-history-based-instance-switch-affordance.html">ADR 0006</a>&#39;s Consequences section for the full raw evidence trail.</li></ol></li><li>✅ No Sovereign auth, role, or plugin behavior is duplicated in native code — true by construction; nothing in this scaffold touches auth (no credentials were entered into the loaded instance during testing — a human tester supplied test credentials mid-session and was told those can&#39;t be typed in by the agent, per a hard rule against entering credentials into any field).</li><li>🟡 Real <strong>physical device</strong> verification — <strong>done on iOS (2026-08-06), still not done on Android.</strong> Built, signed (<code>Apple Development: kasunben@proton.me</code>, automatic signing via <code>-allowProvisioningUpdates</code> once the account was added to Xcode and the resulting developer profile explicitly trusted on-device under Settings → General → VPN &amp; Device Management), installed, and launched on a real, physically connected iPhone 15 Pro (&quot;La Sirena&quot;, iOS build 23F84) via <code>xcrun devicectl</code>. A human tester drove the device directly (this agent has no way to inject touches into physical hardware, unlike Simulator/Emulator) and confirmed, against the real <code>sovereign.openfs.io</code> instance: onboarding shown on first launch; connect and real sign-in succeeded; force-quit and relaunch loaded straight back into the signed-in instance with no onboarding; <strong>a genuine edge-swipe gesture</strong> (not Simulator&#39;s synthetic gesture injection) returned from the loaded instance to the instance manager, the strongest evidence yet for <a href="./../adrs/0006-history-based-instance-switch-affordance.html">ADR 0006</a>; tapping back into the listed instance reloaded it correctly; and an external link (from the sign-in page) opened in Safari, staying out of the primary app view, confirming <a href="./../adrs/0007-navigation-policy-enforcement.html">ADR 0007</a> on real hardware too. Not exercised on real hardware: add/remove of a second instance (only one real instance was available to this device&#39;s network), and the cross-origin cancel-and-warn path specifically. See Risks — the Android half of this item remains a human handoff.</li></ul><p><strong>Implementation notes from this pass, for whoever picks this up next:</strong></p><ul><li><strong>When driving Android back-navigation via <code>adb shell input keyevent KEYCODE_BACK</code>, make sure no text field has keyboard focus first</strong> — a focused <code>EditText</code>/WebView input eats the first back-press to dismiss the IME (<code>GoogleInputMethodService</code> logs it), so a single scripted back-press right after typing looks like it did nothing. Relevant to the now-fixed cold-relaunch bug&#39;s <em>first</em> (&quot;inconclusive&quot;, 2026-08-02) diagnosis, but not the actual root cause of the bug fixed on 2026-08-06 — see below and ADR 0006 for the full trail.</li><li><strong>Don&#39;t declare a platform-specific navigation/back-button finding resolved from only one test shape.</strong> A first correction of the 2026-08-02 &quot;inconclusive&quot; Android finding tested only user-initiated navigation, generalized to &quot;resolved on both platforms,&quot; and was wrong — cold-relaunch-then-back (arguably the most realistic real-world case, since Android kills backgrounded apps routinely) was still broken. When a bug report says &quot;sometimes works, sometimes doesn&#39;t,&quot; the different outcomes are probably different code paths, not flakiness — enumerate the paths before declaring victory on the first one that works.</li><li><strong>Don&#39;t trust the first plausible-looking correlation as the root cause, either — verify it fixes the bug before writing it down as the explanation.</strong> <code>adb shell dumpsys input_method</code> showing the WebView as the IME&#39;s served view immediately after the broken cold-relaunch redirect looked like a strong lead, and was written up as one — but explicitly clearing WebView focus (with delayed retries, to rule out a hydration-timing race) didn&#39;t fix the actual bug. The real cause, found by instrumenting <code>Activity.dispatchKeyEvent</code> with logging rather than reasoning from <code>dumpsys</code> output alone: <code>WebView.canGoBack()</code> reports <code>false</code> and <code>goBack()</code> silently no-ops after this shell&#39;s specific cold-launch redirect pattern, even though <code>copyBackForwardList()</code> correctly shows a valid previous entry — a genuine WebView/Chromium internal-state bug. The fix that actually worked (<code>android/app/src/main/java/fs/sovereign/mobile/MainActivity.java</code>&#39;s <code>dispatchKeyEvent</code> override) bypasses <code>goBack()</code>/<code>canGoBack()</code> entirely rather than trying to prevent the stale state from occurring.</li><li>The Xcode project uses the classic (non-file-system-synchronized) format: new source files must be added to <code>project.pbxproj</code> explicitly (<code>PBXBuildFile</code>, <code>PBXFileReference</code>, the <code>App</code> group, and the <code>Sources</code> build phase) or Xcode silently excludes them from the build — this bit us once already (<code>MainViewController.swift</code> compiled with zero errors from Xcode&#39;s own <code>xcodebuild -resolvePackageDependencies</code> + build, but was never actually part of the target until the pbxproj was fixed by hand, which only surfaced as a runtime &quot;Unknown class ... in Interface Builder file&quot; error and a blank black screen — not a build failure).</li><li>Capacitor 8&#39;s <code>CAPBridgeViewController</code> does <strong>not</strong> conform to <code>WKNavigationDelegate</code> itself; it installs a separate concrete <code>WebViewDelegationHandler</code> (confirmed by reading the resolved <code>Capacitor.swiftinterface</code>, not assumed). <code>MainViewController</code> takes over as <code>navigationDelegate</code> and forwards everything it doesn&#39;t implement back to the original concrete handler — see the class doc comment in <code>ios/App/App/MainViewController.swift</code> for why a concrete-type reference was used instead of the <code>WKNavigationDelegate</code> protocol existential (Swift&#39;s <code>@objc optional</code> protocol-method dispatch is ambiguous for <code>decidePolicyFor</code>&#39;s overload set).</li><li><strong>Never forward a same-origin navigation decision to Capacitor&#39;s own default handler on either platform</strong> — see <a href="./../adrs/0007-navigation-policy-enforcement.html">ADR 0007</a>. Its defaults assume the app&#39;s real content is bundled locally and will redirect a runtime-chosen remote origin externally, which is exactly backwards for this shell.</li><li><strong>The local onboarding page needs explicit <code>pageshow</code>/<code>back_forward</code> handling to work when returned to via back-navigation</strong> — a bfcache restore doesn&#39;t re-run <code>main.ts</code>&#39;s boot script, and even a fresh reload of it would immediately redirect forward again without this. See <a href="./../adrs/0006-history-based-instance-switch-affordance.html">ADR 0006</a>.</li><li><strong>When testing interactively via the iOS Simulator MCP tool, <code>tap</code>/<code>swipe</code> coordinates are in <em>points</em> (e.g. 402×874 for iPhone 17 Pro — the tool states the exact space per device), not screenshot pixels.</strong> Using pixel-scale coordinates from a viewed screenshot (which may itself be further downscaled for display) silently taps outside the visible area or the wrong element with no error — this cost real time before being diagnosed by comparing a screenshot&#39;s actual <code>sips</code>-reported pixel dimensions against the tool&#39;s stated point space. <code>adb shell input tap</code> on Android, by contrast, wants raw device pixels directly (e.g. 1080×2400), not points — the two toolchains don&#39;t share a coordinate convention.</li><li><strong>Getting Android building at all required bypassing Homebrew entirely</strong> in this environment: its Cellar had broken directory ownership (<code>brew install</code> demanded a <code>sudo chown</code> this agent can&#39;t run). JDK 21 (Eclipse Temurin, via Adoptium&#39;s API) and the Android SDK cmdline-tools (Google&#39;s direct zip distribution) were downloaded and extracted straight into this repo&#39;s <code>.toolchain/</code> (gitignored, ~6GB) instead — <code>sdkmanager</code>/<code>avdmanager</code>/<code>gradlew</code> all invoked with <code>JAVA_HOME</code>/ <code>ANDROID_HOME</code> pointed at that directory rather than any system install. <code>android/local.properties</code> (gitignored) points <code>sdk.dir</code> at the same place. None of this is portable to another machine as-is; a real dev environment should just install JDK 21 and Android Studio normally.</li><li><strong>Capacitor&#39;s Android bridge logs plugin calls and console messages to logcat by default</strong> (tags <code>Capacitor</code>, <code>Capacitor/Console</code>, <code>Capacitor/Plugin</code>) — genuinely useful for headless debugging without Chrome remote-debugging, which isn&#39;t available in a fully headless environment. <code>adb logcat -d | grep -iE &quot;chromium|console|capacitor&quot;</code> was how both the navigation-policy bug and the back-navigation hang were actually diagnosed here, not guessed at.</li><li><strong>Building and installing to a real, physically connected iPhone from the command line</strong> (as opposed to Simulator, or opening Xcode&#39;s GUI) needs a few things lined up that aren&#39;t obvious from a simulator-only workflow: (1) an Apple ID must be signed into Xcode&#39;s own Accounts settings — a valid codesigning identity in Keychain Access isn&#39;t enough on its own, <code>xcodebuild</code> reported &quot;No Account for Team&quot; until this was done, and this step needs a human since it requires entering a password/2FA; (2) even with automatic signing (<code>CODE_SIGN_STYLE = Automatic</code> in the project, no <code>DEVELOPMENT_TEAM</code> hardcoded), the build command still needs <code>-allowProvisioningUpdates</code> or it fails with &quot;No profiles for &#39;&lt;bundle id&gt;&#39; were found&quot; instead of generating one; (3) after install, the very first launch attempt via <code>xcrun devicectl device process launch</code> fails with &quot;invalid code signature, inadequate entitlements or its profile has not been explicitly trusted&quot; — this isn&#39;t a build problem, it&#39;s iOS requiring the human to go to Settings → General → VPN &amp; Device Management on the phone itself and explicitly trust the developer profile before anything signed with it will run. None of this is scriptable around; each of the three needs a human in the loop once. The working command sequence: <code>xcodebuild -project ios/App/App.xcodeproj -scheme App -destination &#39;id=&lt;device-udid&gt;&#39; -allowProvisioningUpdates build</code>, then <code>xcrun devicectl device install app --device &lt;device-udid&gt; &lt;path-to-.app&gt;</code>, then (after the on-device trust step) <code>xcrun devicectl device process launch --device &lt;device-udid&gt; fs.sovereign.mobile</code>.</li><li><strong>This agent has no way to inject touches or read the screen of a physical device</strong>, unlike Simulator (<code>simctl</code>) or Emulator (<code>adb input</code> / <code>adb exec-out screencap</code>). Real-device UI verification is therefore a live back-and-forth: the agent drives build/install/launch, a human performs each tap/gesture on the actual hardware and reports what they saw, one step at a time.</li></ul><h4 id="✅-20-14-—-sovereign-deep-link-scheme" tabindex="-1">✅ 20.14 — <code>sovereign://</code> deep link scheme <a class="header-anchor" href="#✅-20-14-—-sovereign-deep-link-scheme" aria-label="Permalink to &quot;✅ 20.14 — `sovereign://` deep link scheme&quot;">​</a></h4><blockquote><p><strong>Identified as a gap against <code>sovereign-desktop</code>, not originally scoped.</strong> A feature-parity audit comparing the two shells found desktop had shipped <code>sovereign://</code> deep linking (its own epic task 17.3) while this repo had no equivalent — no URL scheme registered on either platform, no roadmap task tracking it. This closes that gap.</p><p><strong>Architecture deliberately diverges from desktop&#39;s, and from the obvious <code>@capacitor/app</code> approach — see <a href="./../adrs/0008-deep-link-native-handoff.html">ADR 0008</a> for the full reasoning.</strong> <code>@capacitor/app</code>&#39;s JS-side <code>addListener(&#39;appUrlOpen&#39;, ...)</code> looked like the standard solution but cannot reliably fire once an instance is loaded: <code>onboarding.ts</code>&#39;s <code>loadInstance()</code> does a real top-level <code>location.assign()</code> away from the local page (per <a href="./../adrs/0006-history-based-instance-switch-affordance.html">ADR 0006</a>), destroying whatever JS-level listener was registered from it. Both platforms instead intercept the URL in native code and force the WebView back to the local page with the raw URL attached as <code>?deeplink=</code>, mirroring <code>sovereign-desktop</code>&#39;s own <code>navigate_to_deep_link</code> handoff: native code never resolves the link itself, only hands the raw URL to <code>src/deep-link.ts</code>&#39;s <code>resolveDeepLink</code> (a near-verbatim port of desktop&#39;s own, same test suite ported forward) once the local page has reloaded.</p><p><strong>Two genuine, previously-latent bugs were found and fixed while getting this to actually work end-to-end — not implementation mistakes in this task&#39;s own new code, but real gaps in existing mechanisms that nothing before this task ever exercised:</strong></p><ol><li><strong>iOS: <code>MainViewController.swift</code>&#39;s <code>localModeScripts</code> &quot;backup&quot; was never actually independent of the WebView&#39;s live script storage.</strong><code>capacitorDidLoad()</code>&#39;s <code>localModeScripts = webView.configuration .userContentController.userScripts</code> looked like a snapshot but wasn&#39;t — confirmed by instrumenting with <code>NSLog</code> and watching the count drop from 10 (captured correctly) to 1 (after <code>enterRemoteMode()</code>&#39;s own <code>removeAllUserScripts()</code> + one <code>addUserScript()</code> call) to 0 (after <code>enterLocalMode()</code>&#39;s <em>own</em> <code>removeAllUserScripts()</code> call, moments before it tried to restore from the very array that call had just emptied). The observable symptom: reloading the local page after having shown a remote instance left <code>window.Capacitor.PluginHeaders</code> empty, so any <code>@capacitor/preferences</code> call threw <code>&quot;Preferences&quot; plugin is not implemented on ios</code> — silently stranding <code>boot()</code> on the static pre-boot placeholder forever, no visible error. This was invisible before this task because the only prior &quot;return to local&quot; path — the edge-swipe back gesture (ADR 0006) — resumes the page from WKWebView&#39;s back/forward cache rather than reloading it, so <code>window.Capacitor</code> was never actually torn down for that path to begin with. <strong>Fixed</strong> by reconstructing genuinely independent <code>WKUserScript</code> values (<code>source</code>/<code>injectionTime</code>/<code>isForMainFrameOnly</code> read individually, not the array reference held onto) — <code>MainViewController.swift</code>&#39;s <code>capacitorDidLoad()</code>.</li><li><strong>Android: <code>src/deep-link.ts</code>&#39;s original <code>new URL(rawUrl).hostname</code> approach doesn&#39;t work in Chromium WebView at all, for any input.</strong> Confirmed via the same on-device debug harness (a visible <code>&lt;pre&gt;</code> dump of the parsed URL&#39;s fields, since <code>adb logcat</code> redacts URLs by default): for a non-special scheme like <code>sovereign:</code>, this WebView build (Chromium 113) leaves <code>.hostname</code>/<code>.host</code> empty and folds the entire <code>//host/path</code> into <code>.pathname</code> instead — a genuine engine-level interop gap in non-special-scheme authority parsing (WebKit on iOS parses the identical string correctly). <strong>Fixed</strong> by parsing the scheme/host/path directly from the string (<code>src/deep-link.ts</code>) rather than trusting <code>URL</code>&#39;s authority recognition for anything but the <em>stored</em> instance URLs, which are ordinary <code>https://</code> URLs and parse identically everywhere — this also made the existing Vitest suite a false positive for this exact bug, since Node&#39;s <code>URL</code> implementation parses <code>sovereign://</code> authorities correctly and had no way to catch a real-WebView-only divergence.</li></ol><p><strong>Verification, both platforms, on real Simulator/Emulator runs, both bugs caught and fixed via genuine device-attached debugging (<code>NSLog</code> + <code>log stream</code> on iOS; <code>adb logcat</code> on Android — not assumed from reading code):</strong></p><ul><li>✅ iOS Simulator (iPhone 17 Pro): both a known-host deep link (<code>sovereign://sovereign.openfs.io/plugins/console</code>, fired while the local onboarding page was showing) and an unknown-host one (<code>sovereign://not-added.example/plugins/console</code>, fired while a <em>remote</em> instance was already loaded — the harder, bug-triggering case) resolved correctly: the known case navigated straight to the real instance (redirected to its own sign-in page, unauthenticated, as expected); the unknown case rendered onboarding pre-filled with <code>https://not-added.example</code>, existing stored instances still listed.</li><li>✅ Android Emulator (<code>sovereign_mobile_test</code> AVD): the identical two cases, fired via <code>adb shell am start -a android.intent.action.VIEW -d &quot;sovereign://...&quot;</code> against an already-running process (confirmed routed through <code>onNewIntent</code>, not a fresh process, via <code>singleTask</code> launch mode) — same outcomes, <code>adb logcat</code> confirmed clean <code>Preferences</code> plugin round-trips with no errors on both paths.</li><li>✅ <code>pnpm test</code> — 24/24 pass (9 deep-link tests, including one added for case-insensitive scheme/host matching, a real behavior change from the Android-driven rewrite).</li><li>✅ <code>pnpm typecheck</code> / <code>pnpm lint</code> / <code>pnpm format:check</code> — clean.</li><li>❌ <strong>Not verified</strong>: a real tap on a <code>sovereign://</code> link from another app (email, notes, browser) rather than <code>open_url</code>/<code>am start</code> — same category as every other native-trigger gap in this repo (no way to simulate a genuine cross-app tap in Simulator/Emulator); the OS-level &quot;Open in Sovereign?&quot; confirmation dialog on iOS did appear correctly when triggered this way, which is the strongest available signal short of that.</li><li>Real physical-device verification not attempted this session (no physical device available) — same gap as task 20.1&#39;s own Android entry above.</li></ul></blockquote><p><strong>Goal:</strong> Register a <code>sovereign://</code> URL scheme so links in emails, browsers, and other apps open this app and navigate to the correct instance and path, matching <code>sovereign-desktop</code>&#39;s existing epic task 17.3.</p><p><strong>Deliverables:</strong></p><ul><li><code>src/deep-link.ts</code> — <code>resolveDeepLink(rawUrl, instances)</code>: parses <code>sovereign://&lt;host&gt;/&lt;path&gt;</code> directly from the string (not via <code>URL</code> authority parsing — see bug #2 above), matches <code>host</code> against stored instances by hostname, returns a known/unknown/<code>null</code> result. Ported from <code>sovereign-desktop</code>&#39;s own module and test suite.</li><li><code>src/main.ts</code> — <code>handleDeepLink()</code>, checked via <code>?deeplink=</code> before the stored-active-instance shortcut in <code>boot()</code>. A known host: <code>setActiveUrl</code> then <code>location.assign()</code> (not <code>.replace()</code> — matches ADR 0006). An unknown host: <code>renderOnboarding()</code> pre-filled.</li><li><code>src/onboarding.ts</code> — new <code>OnboardingOptions</code> (<code>prefillUrl</code>, <code>pendingPath</code>), ported from <code>sovereign-desktop</code>&#39;s own <code>onboarding.ts</code>.</li><li><strong>iOS</strong>: <code>Info.plist</code>&#39;s <code>CFBundleURLTypes</code> registers the scheme. <code>AppDelegate.swift</code>&#39;s <code>application(_:open:options:)</code> intercepts <code>sovereign://</code> URLs directly (bypassing Capacitor&#39;s own proxy for this one case) and calls <code>MainViewController.loadDeepLink(_:)</code>, which <code>webView.load()</code>s <code>capacitor://localhost/?deeplink=&lt;url&gt;</code>. Also fixes bug #1 above in <code>capacitorDidLoad()</code>.</li><li><strong>Android</strong>: <code>AndroidManifest.xml</code>&#39;s new <code>&lt;intent-filter&gt;</code> (alongside the existing <code>MAIN</code>/<code>LAUNCHER</code> one) registers the scheme. <code>MainActivity.java</code>&#39;s <code>handleDeepLinkIntent()</code>, called from both <code>load()</code> (cold launch) and <code>onNewIntent()</code> (warm launch, routed here by the existing <code>singleTask</code> launch mode), calls <code>webView.loadUrl(LOCAL_ORIGIN + &quot;?deeplink=&quot; + Uri.encode(...))</code>.</li><li><a href="./../adrs/0008-deep-link-native-handoff.html">ADR 0008</a> — the native-handoff design decision and both bugs&#39; root-cause writeups.</li><li><code>src/__tests__/deep-link.test.ts</code> — 9 tests, ported from desktop&#39;s suite plus one new case-insensitivity test.</li></ul><p><strong>SRS reference:</strong> §3.12 (mobile), §3.19 (desktop equivalent, same requirement)</p><p><strong>Review checklist:</strong></p><ul><li>Opening <code>sovereign://&lt;known-host&gt;/&lt;path&gt;</code> navigates directly to that instance&#39;s matching path</li><li>Opening <code>sovereign://&lt;unknown-host&gt;/&lt;path&gt;</code> shows the add-instance prompt pre-filled with that host, and resumes to <code>&lt;path&gt;</code> once added</li><li>Works both from a cold launch and while the app is already running, including while a remote instance is currently loaded (the case that exposed both bugs above)</li><li><code>pnpm test</code> passes, including <code>resolveDeepLink</code>&#39;s full suite</li></ul><h2 id="risks" tabindex="-1">Risks <a class="header-anchor" href="#risks" aria-label="Permalink to &quot;Risks&quot;">​</a></h2><ul><li><strong>Real-device verification is a documented human handoff.</strong> An agent can build, wire CI, and prepare a checklist, but driving the actual taps and gestures requires a human with the physical device in hand — see sovereign workstream 0002&#39;s Risks section and <code>docs/pwa-real-device-testing.md</code> in the <code>sovereign</code> monorepo. <strong>Partly discharged for iOS (2026-08-06):</strong> with a real iPhone connected over USB and a human tester relaying what they saw, this agent handled the build/ sign/install/launch side (<code>xcodebuild -allowProvisioningUpdates</code> + <code>xcrun devicectl</code>) while the human performed every tap and gesture — see the physical-device checklist entry above. <strong>Android physical-device verification is still fully open</strong> — no real Android device was available this session.</li><li><strong>Apple guideline 4.2 (minimum functionality)</strong> applies to WebView wrappers. Well precedented by Nextcloud/Bitwarden/Element, and the self-hosted-client category is the one Apple accommodates — but non-zero risk, and the one most likely to change this epic&#39;s plan.</li><li><strong>WKWebView data eviction</strong> under storage pressure or prolonged non-use — see <a href="./../adrs/0003-cookie-in-webview-auth.html">ADR 0003</a> and <a href="./../research/0003-webview-offline-behavior.html">research 0003</a>.</li></ul><h2 id="related-docs" tabindex="-1">Related docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related docs&quot;">​</a></h2><ul><li><a href="./../../CONCEPT.html">CONCEPT.md</a></li><li><a href="./../adrs/0001-capacitor-as-shell-technology.html">ADR 0001</a>, <a href="./../adrs/0002-universal-one-binary-distribution.html">ADR 0002</a>, <a href="./../adrs/0003-cookie-in-webview-auth.html">ADR 0003</a>, <a href="./../adrs/0005-server-url-not-bundled-assets.html">ADR 0005</a></li><li><a href="./../research/0001-shell-and-bridge-technology-choice.html">research 0001</a>, <a href="./../research/0003-webview-offline-behavior.html">research 0003</a></li></ul>',32)])])}const u=o(a,[["render",s]]);export{g as __pageData,u as default};
